package com.enterprise.reference.controller;

import com.enterprise.reference.service.AccountService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.time.Instant;

@RestController
@RequestMapping(path = "/api/v1/accounts", produces = MediaType.APPLICATION_JSON_VALUE)
public class SampleAccountController {

    private final AccountService accountService;

    public SampleAccountController(AccountService accountService) {
        this.accountService = accountService;
    }

    public record AccountResponse(
        String accountId,
        String accountHolder,
        BigDecimal balance,
        String status,
        Instant lastUpdated
    ) {}

    public record BalanceAdjustmentRequest(
        @NotBlank(message = "Adjustment reason is mandatory")
        String reason,

        @NotNull(message = "Adjustment amount is mandatory")
        @Positive(message = "Adjustment amount must be positive")
        BigDecimal amount
    ) {}

    @GetMapping("/{accountId}")
    public ResponseEntity<AccountResponse> getAccount(@PathVariable String accountId) {
        return ResponseEntity.ok(accountService.getAccount(accountId));
    }

    @PostMapping("/{accountId}/adjustments")
    public ResponseEntity<AccountResponse> adjustBalance(
            @PathVariable String accountId,
            @Valid @RequestBody BalanceAdjustmentRequest request) {
        AccountResponse response = accountService.adjustBalance(accountId, request.amount(), request.reason());
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }
}

package com.enterprise.reference.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.net.URI;
import java.time.Instant;
import java.util.NoSuchElementException;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleIllegalArgument(IllegalArgumentException ex) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, ex.getMessage());
        problem.setTitle("Validation Invariant Failure");
        problem.setType(URI.create("urn:problem:validation-error"));
        problem.setProperty("timestamp", Instant.now());
        return problem;
    }

    @ExceptionHandler(NoSuchElementException.class)
    public ProblemDetail handleNotFound(NoSuchElementException ex) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
        problem.setTitle("Resource Not Found");
        problem.setType(URI.create("urn:problem:resource-not-found"));
        problem.setProperty("timestamp", Instant.now());
        return problem;
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail handleMethodArgumentNotValid(MethodArgumentNotValidException ex) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(
            HttpStatus.BAD_REQUEST,
            "Request validation constraint violated"
        );
        problem.setTitle("Bad Request");
        problem.setType(URI.create("urn:problem:constraint-violation"));
        problem.setProperty("timestamp", Instant.now());
        return problem;
    }
}

package com.enterprise.reference.service;

import com.enterprise.reference.controller.SampleAccountController.AccountResponse;
import com.enterprise.reference.repository.AccountRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.NoSuchElementException;

@Service
@Transactional
public class AccountService {

    private final AccountRepository accountRepository;

    public AccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    @Transactional(readOnly = true)
    public AccountResponse getAccount(String accountId) {
        if (!accountRepository.exists(accountId)) {
            throw new NoSuchElementException("Account not found: " + accountId);
        }
        BigDecimal balance = accountRepository.getBalance(accountId);
        return new AccountResponse(accountId, "Enterprise Customer", balance, "ACTIVE", Instant.now());
    }

    public AccountResponse adjustBalance(String accountId, BigDecimal amount, String reason) {
        if (amount == null || amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Adjustment amount must be positive");
        }
        if (!accountRepository.exists(accountId)) {
            throw new NoSuchElementException("Account not found: " + accountId);
        }
        BigDecimal current = accountRepository.getBalance(accountId);
        BigDecimal newBalance = current.add(amount);
        accountRepository.updateBalance(accountId, newBalance);
        return new AccountResponse(accountId, "Enterprise Customer", newBalance, "ACTIVE", Instant.now());
    }
}
